{
  "application": "data-visualization",
  "case_id": "case-climate-ocean-health-multi-indicator-timeseries",
  "language": "en",
  "style": {
    "theme": "scientific",
    "audience": "researchers and policy makers",
    "tone": "rigorous, publication-ready, information-dense"
  },
  "goal": [
    {
      "id": "ocean-health-divergence",
      "insight": "Show the simultaneous multi-indicator deterioration of ocean health from 1990 to 2024 by overlaying four time series with independent y-axes so their contrasting trend directions are visually apparent"
    },
    {
      "id": "coral-collapse-acceleration",
      "insight": "Emphasize the accelerating decline in coral cover percentage, particularly the steepening drop after 2015"
    },
    {
      "id": "temperature-anomaly-rise",
      "insight": "Highlight the upward trajectory of sea surface temperature anomaly, drawing attention to the sharp increase in the most recent years"
    },
    {
      "id": "plastic-exponential-growth",
      "insight": "Make the near-exponential growth curve of ocean plastic pollution visually prominent against the other more gradual trends"
    },
    {
      "id": "dual-axis-encoding",
      "insight": "Use distinct axis scales, colors, and line styles for each of the four indicators so viewers can compare trend shapes despite different units (°C anomaly, pH, %, million metric tons)"
    }
  ]
}

